// Virtual styling tools use retailer widths; they never collect prescriptions.
export const isVerifiedFrame=p=>['sunglasses','eyeglasses'].includes(p?.type)&&!!p.frameProfile;
const ease=x=>{x=Math.max(0,Math.min(1,x));return Math.max(0,Math.min(1,x*x*x*(x*(x*6-15)+10)));};
export function frameGesture(time,reduced=false){if(reduced||!Number.isFinite(time))return 0;return ease((time-.45)/.95)*(1-ease((time-2.3)/1.1));}
export function framePose(time,reduced=false,rest=null){
 const reach=frameGesture(time,reduced);
 return {reach,hands:[-1,1].map((sign,i)=>{const a=rest?.[i]||{x:sign*6.5,y:28.4,z:8};return {x:a.x+(sign*3.4-a.x)*reach,y:a.y+(44.9-a.y)*reach,z:a.z+(3.7-a.z)*reach+Math.sin(Math.PI*reach)*3};})};
}
export function frameFactsHTML(p,esc){if(!isVerifiedFrame(p))return '';const f=p.frameProfile;return `<dl class="frame-facts"><dt>Frame color</dt><dd>${esc(p.colorName)}</dd><dt>Frame material</dt><dd>${esc(f.material)}</dd><dt>Source widths</dt><dd>${p.sizes.map(esc).join(' · ')}</dd>${f.optical?`<dt>Exact frame reference</dt><dd>${esc(p.referenceSKU)}</dd><dt>Published dimensions · mm</dt><dd>Lens ${f.lensWidthMM} · bridge ${f.bridgeMM} · temple ${f.templeMM} · lens height ${f.lensHeightMM} · full front ${f.frameWidthMM}<small>${esc(f.dimensionNote)}</small></dd><dt>Lens styling</dt><dd>Clear optical frame · no vision correction is simulated</dd>`:''}<dt>Price reference</dt><dd>${f.optical?'Dated base USD offer with standard clear lenses. Paid lens upgrades and other extras are excluded.':'Published starting USD offer. Real lens customization changes the price.'}</dd></dl><p class="hint">Virtual styling preview · game fit is simulated. Compare the source photograph and widths. Prescription and lens ordering are outside this game.</p>`;}
export function opticalNotebookHTML(st,esc){return `<div class="modal-body optical-notebook"><span class="eyebrow">LOOK, COMPARE, THEN TRY</span><h3>A frame has more than one measurement.</h3><p>The manufacturer’s width labels describe these two selected frames. Lens width, bridge gap, temple length and full front width are different measurements. They do not measure your face.</p><div class="optical-source-grid">${st.products.filter(p=>p.frameProfile?.optical).map(p=>`<section><h3>${esc(p.name)}</h3>${frameFactsHTML(p,esc)}<a href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">Official selected frame & specifications ↗</a></section>`).join('')}</div><p class="hint">Reading this notebook is free and pauses time. Trying a frame uses the displayed game time; no purchase is made until checkout.</p><button class="button secondary wide" data-action="collection-open">Back to the collection desk</button></div>`;}
